#!/usr/bin/env python3
import csv
import json
from copy import deepcopy
from pathlib import Path

ROOT = Path('/root')


def load_json(name):
    with open(ROOT / name, 'r', encoding='utf-8') as f:
        return json.load(f)


def load_csv(name):
    with open(ROOT / name, 'r', encoding='utf-8', newline='') as f:
        return list(csv.DictReader(f))


def is_nonempty(value):
    return value is not None and str(value).strip() != ''


def to_float(value, default=0.0):
    if not is_nonempty(value):
        return default
    return float(value)


def to_int(value):
    return int(float(str(value).strip()))


def money(value):
    return round(float(value), 2)


def all_panels(manifest):
    panels = []
    for cluster in manifest.get('service_clusters', []):
        for panel in cluster.get('panels', []):
            panels.append(panel)
    return panels


def main():
    manifest = load_json('panel_manifest.json')
    holdouts = load_json('holdouts.json')
    template = load_json('report_template.json')

    shipper_rows = load_csv('shipper_cost.csv')
    contract_rows = load_csv('contract_terms.csv')
    adjustment_rows = load_csv('network_adjustments.csv')
    override_rows = load_csv('lab_capacity_overrides.csv')

    excluded_codes = {
        row.get('panel_code')
        for row in holdouts.get('holdouts', [])
        if row.get('holdout_state') == 'exclude'
    }

    retained = [
        p for p in all_panels(manifest)
        if p.get('analysis_mode') == 'review' and p.get('panel_code') not in excluded_codes
    ]

    shipper_by_class = {
        row['shipper_class']: to_float(row['shipper_cost_usd'])
        for row in shipper_rows
    }
    adjustment_by_tier = {
        row['network_tier']: to_float(row['network_adjustment_per_run_per_lab_usd'])
        for row in adjustment_rows
    }

    # Highest numeric approved rev with non-empty active_labs for each panel_code.
    best_override = {}
    for row in override_rows:
        if row.get('approval') != 'approved':
            continue
        if not is_nonempty(row.get('rev')) or not is_nonempty(row.get('active_labs')):
            continue
        rev = to_int(row['rev'])
        code = row.get('panel_code')
        active_labs = to_int(row['active_labs'])
        if code not in best_override or rev > best_override[code]['rev']:
            best_override[code] = {'rev': rev, 'active_labs': active_labs}

    panel_results = []
    for panel in retained:
        refs = {panel.get('panel_name')}
        refs.update(panel.get('alias_labels') or [])
        current_matches = [
            row for row in contract_rows
            if row.get('status_flag') == 'current' and row.get('panel_ref') in refs
        ]
        if not current_matches:
            raise ValueError(f"No current contract row found for {panel.get('panel_code')}")
        contract = max(current_matches, key=lambda r: r.get('effective_week', ''))
        base_payment = to_float(contract['base_payment_per_run_per_lab_usd'])

        network_tier = panel.get('network_tier')
        network_adjustment = adjustment_by_tier.get(network_tier, 0.0)
        active_labs = best_override.get(panel['panel_code'], {}).get(
            'active_labs', to_int(panel['default_active_labs'])
        )
        shipper_cost = shipper_by_class[panel['shipper_class']]
        reagent_cost_per_1000 = to_float(panel['reagent_cost_per_1000_tests_usd'])
        total_payment = base_payment + network_adjustment

        def calc(runs_per_year, tests_per_lab_per_run):
            revenue = total_payment * active_labs * runs_per_year
            reagent = reagent_cost_per_1000 * active_labs * tests_per_lab_per_run * runs_per_year / 1000.0
            shipper = shipper_cost * runs_per_year
            margin = revenue - reagent - shipper
            return revenue, reagent, shipper, margin

        rev14, reagent14, shipper14, margin14 = calc(26, to_float(panel['tests_per_lab_per_run_14_day']))
        rev28, reagent28, shipper28, margin28 = calc(13, to_float(panel['tests_per_lab_per_run_28_day']))
        diff = margin28 - margin14

        panel_results.append({
            'panel_code': panel['panel_code'],
            'panel_name': panel['panel_name'],
            'network_tier': network_tier,
            'shipper_class': panel['shipper_class'],
            'active_labs': active_labs,
            'base_payment_per_run_per_lab_usd': money(base_payment),
            'network_adjustment_per_run_per_lab_usd': money(network_adjustment),
            'total_payment_per_run_per_lab_usd': money(total_payment),
            'reagent_cost_per_1000_tests_usd': money(reagent_cost_per_1000),
            'shipper_cost_usd': money(shipper_cost),
            'tests_per_lab_per_run_14_day': money(panel['tests_per_lab_per_run_14_day']),
            'annual_revenue_14_day_usd': money(rev14),
            'annual_reagent_cost_14_day_usd': money(reagent14),
            'annual_shipper_cost_14_day_usd': money(shipper14),
            'annual_margin_14_day_usd': money(margin14),
            'tests_per_lab_per_run_28_day': money(panel['tests_per_lab_per_run_28_day']),
            'annual_revenue_28_day_usd': money(rev28),
            'annual_reagent_cost_28_day_usd': money(reagent28),
            'annual_shipper_cost_28_day_usd': money(shipper28),
            'annual_margin_28_day_usd': money(margin28),
            'annual_margin_difference_28_minus_14_usd': money(diff),
        })

    panel_results.sort(key=lambda row: row['panel_code'])

    total14 = sum(p['annual_margin_14_day_usd'] for p in panel_results)
    total28 = sum(p['annual_margin_28_day_usd'] for p in panel_results)
    totaldiff = sum(p['annual_margin_difference_28_minus_14_usd'] for p in panel_results)
    absdiff = abs(totaldiff)
    decision = 'adopt_28_day' if absdiff < 6000 else 'keep_14_day'
    if decision == 'adopt_28_day':
        justification = (
            'Adopt the 28-day cadence because the absolute total annual margin difference '
            f'({money(absdiff):.2f}) is below the 6000.00 switch threshold.'
        )
    else:
        justification = (
            'Keep the 14-day cadence because the absolute total annual margin difference '
            f'({money(absdiff):.2f}) is greater than or equal to the 6000.00 switch threshold.'
        )

    report = deepcopy(template)
    report['analysis'] = {
        'assumptions': {
            'runs_per_year_14_day': 26,
            'runs_per_year_28_day': 13,
            'switch_threshold_usd': 6000,
            'override_rule': 'highest numeric approved rev with non-empty active_labs, else default_active_labs',
            'holdout_rule': 'exclude holdout_state=exclude',
            'adjustment_rule': 'missing network_tier adjustment defaults to 0.0',
        },
        'panels': panel_results,
        'totals': {
            'total_annual_margin_14_day_usd': money(total14),
            'total_annual_margin_28_day_usd': money(total28),
            'total_annual_margin_difference_28_minus_14_usd': money(totaldiff),
            'absolute_total_margin_difference_usd': money(absdiff),
        },
        'recommendation': {
            'decision': decision,
            'justification': justification,
        },
    }

    with open(ROOT / 'diagpanel_policy_report.json', 'w', encoding='utf-8') as f:
        f.write(json.dumps(report, indent=2))
        f.write('\n')

    summary_lines = [
        'Diagpanel policy summary',
        f"Total 14-day margin: {money(total14):.2f}",
        f"Total 28-day margin: {money(total28):.2f}",
        f"Absolute difference: {money(absdiff):.2f}",
        f"Final decision: {decision}",
    ]
    with open(ROOT / 'diagpanel_policy_summary.md', 'w', encoding='utf-8') as f:
        f.write('\n'.join(summary_lines))
        f.write('\n')


if __name__ == '__main__':
    main()
